import {workshopRoute,listeningWorkshop} from './listening-links.js?v=2.1.0';
import {grammarEditorHTML,mountGrammarEditor} from './grammar-editor.js?v=2.1.0';
import {MEDIA,SOURCES,TOPICS,FORM_LINES,FORMS,FACT_CHECKS} from './data.js?v=2.1.0';
import {emptyJournal,decodeJournal,validateJournal,startRecall,hideRecall,compareRecall,saveAttempt,scoreRecall,termCoverage,rhymeScheme,endWords} from './core.js?v=2.1.0';
const $=selector=>document.querySelector(selector),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes=[['start','Einstieg'],['hoeren','Tracks & Themen'],['form','Gedichtform'],['merken','Abrufen'],['werkstatt','Selbst schreiben'],['quellen','Quellen']];
let state=emptyJournal(),recall=null,recallSaved=false,storage=true,beatTimer=null,audio=null,beatNumber=-1;
try{const old=localStorage.getItem('wartke-form-gedaechtnis-v1');if(old)state=decodeJournal(old);}catch{storage=false;}
const note=(key,fallback='')=>state.notes[key]??fallback;
function toast(text){$('#status').textContent=text;$('#status').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#status').classList.remove('show'),4500);}
function save(){try{localStorage.setItem('wartke-form-gedaechtnis-v1',JSON.stringify(state));}catch{storage=false;toast('Der Browserspeicher ist nicht verfügbar. Sichere dein Journal als Datei.');}}
function setNote(key,value){state.notes[key]=String(value);save();}
function field(key,label,placeholder=''){return `<label class="field" for="note-${key}">${esc(label)}</label><textarea id="note-${key}" data-note="${key}" maxlength="30000" placeholder="${esc(placeholder)}">${esc(note(key))}</textarea>`;}
function bindNotes(){document.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>setNote(el.dataset.note,el.value)));}
function source(id){return SOURCES.find(item=>item.id===id);}
function sourceLink(id){const s=source(id);return `<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`;}
function head(label,title,intro){return `<div class="route-head"><p class="eyebrow">${label}</p><h1>${title}</h1><p class="intro">${intro}</p></div>`;}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
$('.dialog-close').onclick=()=>$('#dialog').close();
function stopBeat(){clearInterval(beatTimer);beatTimer=null;beatNumber=-1;document.querySelectorAll('.beat').forEach(el=>el.classList.remove('active'));}
function render(){stopBeat();const raw=workshopRoute(location.hash).route,route=routes.some(item=>item[0]===raw)?raw:'start';$('#navigation').innerHTML=routes.map(([id,title])=>`<a href="#${id}" ${route===id?'aria-current="page"':''}>${title}</a>`).join('');$('#main').innerHTML=({start:landing,hoeren:listening,form:formPage,merken:memoryPage,werkstatt:workshop,quellen:sourcesPage}[route])();if(route==='hoeren'||route==='start'){bindMedia();}if(route==='hoeren')bindTrackFilters();if(route==='start')bindSpark();if(route==='form')bindForm();if(route==='merken')bindMemory();if(route==='werkstatt'){bindWorkshop();bindSpark();}bindNotes();}
function videoCover(item){return `<div class="player original-cover" id="player-${item.id}"><button data-media="${item.id}" aria-label="${esc(item.title)} · Originalvideo laden">${item.kind==='youtube'?`<img src="https://i.ytimg.com/vi/${item.video}/hqdefault.jpg" alt="Vorschaubild des Originalvideos von Bodo Wartke" loading="lazy" referrerpolicy="no-referrer">`:`<span class="cover-word">${esc(item.title)}</span>`}<span class="play-label"><b aria-hidden="true">▶</b> Original ansehen</span></button></div>`;}
function artistLinks(){return `<nav class="artist-links" aria-label="Bodo Wartkes Originalkanäle"><a href="https://www.bodowartke.de/" target="_blank" rel="noopener noreferrer">Bodos Website ↗</a><a href="https://www.instagram.com/bodowartke/" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="https://www.youtube.com/@bodo_wartke" target="_blank" rel="noopener noreferrer">YouTube ↗</a></nav>`;}
function spark(){return `<section class="spark-stage"><div><p class="eyebrow">Jetzt du · Laut lesen erlaubt</p><h2>Welches Wort bringt<br>deine Zunge ins Stolpern?</h2><p>Ein Schulwort, ein Strassenname, ein Ding aus deiner Hosentasche. Lass es eine kleine Geschichte anfangen.</p><label class="field" for="spark-word">Dein Wort</label><input id="spark-word" type="text" maxlength="80" value="${esc(note('spark-word','Quantenquark'))}"><div class="actions"><button data-spark="klang" aria-pressed="true">Mit dem Anlaut spielen</button><button data-spark="figur" aria-pressed="false">Das Wort als Figur</button><button data-spark="wendung" aria-pressed="false">Eine Wendung versuchen</button></div></div><div class="spark-paper"><p class="small">Deine erste Zeile · frei bearbeitbar</p><label class="sr-only" for="spark-line">Deine erste Zeile</label><textarea id="spark-line" data-note="spark-line" maxlength="5000" placeholder="Hier beginnt deine Geschichte …">${esc(note('spark-line'))}</textarea><p id="spark-hint" class="small" role="status"></p><button class="primary" id="spark-next">Diese Zeile mitnehmen</button><p class="small">Eigene Schreibanregungen dieser Werkstatt. Kein Originaltext von Wartke.</p></div></section>`;}
function bindSpark(){let mode='klang';const input=$('#spark-word'),line=$('#spark-line');if(!input)return;const draw=()=>{const word=input.value.trim()||'Mein Wort',first=Array.from(word)[0].toLocaleUpperCase('de');line.value=mode==='figur'?`${word} kam zu spät. Der Rest der Welt wartete schon.`:mode==='wendung'?`Ich wollte ${word} erklären. Jetzt erklärt es mich.`:`${word}. ${first}… ${first}… Wer oder was könnte hier auftauchen?`;setNote('spark-word',input.value);setNote('spark-line',line.value);$('#spark-hint').textContent=mode==='klang'?'Ersetze die Punkte durch zwei Wörter mit demselben Anfangslaut. Sprich die Zeile langsam.':mode==='figur'?'Was tut dein Wort als Nächstes? Gib ihm einen Wunsch oder ein Problem.':'Ändere den Schluss so, dass er eine neue Bedeutung öffnet.';document.querySelectorAll('[data-spark]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.spark===mode)));};document.querySelectorAll('[data-spark]').forEach(b=>b.onclick=()=>{mode=b.dataset.spark;draw();});input.oninput=draw;if(!line.value.trim())draw();else $('#spark-hint').textContent='Deine letzte erste Zeile ist wieder da. Verändere sie oder probiere eine andere Richtung.';$('#spark-next').onclick=()=>{setNote('spark-line',line.value);setNote('studio-impuls',line.value);setNote('workshop-topic','eigen');if(workshopRoute(location.hash).route==='werkstatt'){$('#dg-take-spark').click();}else location.hash='#werkstatt';};}
function landing(){return `<section class="performance-hero"><div class="performance-copy"><p class="eyebrow">Bodo Wartke · Klavierkabarett & Zungenbrecher</p><h1>Hör mal,<br>was Sprache <em>kann.</em></h1><p class="intro">Ein Wort wird länger. Ein Reim zieht den nächsten nach sich. Plötzlich ist da eine ganze Geschichte. Bodo Wartke spielt mit Sprache – am Klavier, vor der Kamera und mitten in einem Fachbegriff.</p>${artistLinks()}<div class="actions"><a class="button primary" href="#hoeren">Mehr Originale ansehen</a><a class="button" href="#werkstatt">Selber mit Wörtern spielen</a></div></div><article class="feature-performance"><p class="performance-sticker">Wort wird Geschichte</p>${videoCover(MEDIA.find(m=>m.id==='barbara'))}<div class="performance-caption"><h2>Barbaras Rhabarberbar</h2><p>Bodo Wartke feat. Marti Fischer · Originalvideo</p><a href="#werkstatt?hoerbeispiel=barbara">Eine eigene Wortgeschichte anfangen →</a></div></article></section><section class="performance-picks"><p class="eyebrow">Drei Arten, sich festzuhören</p><div class="grid three">${['er','dach','mito'].map(id=>{const item=MEDIA.find(m=>m.id===id);return `<article class="panel media-card">${videoCover(item)}<p class="eyebrow">${id==='er'?'Fachwort im Flow':id==='dach'?'Knoten in der Zunge':'Wissen mit Rhythmus'}</p><h2>${esc(item.title)}</h2><p>${esc(item.description)}</p><a class="button" href="#werkstatt?hoerbeispiel=${id}">${id==='dach'?'Eigene Lautfolgen erfinden':'Mit diesem Impuls schreiben'} →</a></article>`;}).join('')}</div></section><section class="beyond-biology section-gap"><p class="eyebrow">Drei weitere Originaltracks</p><h2>Grundrechte. Religion. Ein Wald.</h2><p>Was kann ein Lied erklären – und wo will es etwas verändern?</p><div class="grid three">${['grundgesetz','schriften','wald'].map(id=>{const item=MEDIA.find(m=>m.id===id);return `<article class="panel media-card">${videoCover(item)}<p class="eyebrow">${esc(item.subject)}</p><h2>${esc(item.title)}</h2><p>${esc(item.description)}</p><a class="button" href="#hoeren?thema=${item.transfer}">Track, Hörnotiz und Schreibimpuls →</a></article>`;}).join('')}</div></section>${spark()}<section class="grid section-gap"><article class="panel blue"><p class="eyebrow">Was bleibt hängen?</p><h2>Der Reim? Die Idee? Beides?</h2><p>Probier es aus: Hör eine Stelle, mach das Video zu und sag, was du noch weisst. Ein guter Klang kann beim Erinnern helfen. Den Zusammenhang erklären ist der nächste Versuch.</p><a href="#merken">Den eigenen Kopf testen →</a></article><article class="panel gold"><p class="eyebrow">Über den Klang hinaus</p><h2>Warum funktioniert die Zeile?</h2><p>Verschiebe Zeilen. Markiere Endklänge. Lege einen Takt darunter. Du hörst sofort, was sich verändert.</p><a href="#form">Mit einer Strophe spielen →</a></article></section>`;}
function listening(){return head('Wartkes Originale · nach Themen','Welcher Track<br><em>bleibt bei dir?</em>','Biologie-Rap, Sprachspiel, Grundrechte, Religionskritik oder Protestlied: Wähle ein Original. Die politischen und religionskritischen Lieder formulieren Positionen; sie sind keine neutralen Lehrtexte.')+`<div class="track-filters" role="group" aria-label="Originaltracks nach Thema">${[['alle','Alle Tracks'],['politik','Geschichte & Politik'],['ethik','Religion & Ethik'],['geografie','Geografie & Umwelt'],['bio','Biologie'],['deutsch','Sprache']].map(([id,label])=>`<button data-track-filter="${id}" aria-pressed="false">${label}</button>`).join('')}</div><p class="small" id="track-count" role="status"></p><div class="grid">${MEDIA.map(item=>`<article id="track-${item.id}" data-track-topic="${item.transfer}" class="panel media-card"><p class="eyebrow">${esc(item.subject)} · Originalbeitrag</p><h2>${esc(item.title)}</h2><p class="small">${esc(item.provider)}${item.category?` · ${esc(item.category)}`:''}</p><p class="description">${esc(item.description)}</p>${videoCover(item)}<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Original beim Anbieter öffnen</a>${item.official?`<p class="small"><a href="${esc(item.official)}" target="_blank" rel="noopener noreferrer">Entstehung und Hintergrund bei Wartke</a></p>`:''}<details><summary>Hör- und Untersuchungsauftrag</summary><h3>Beim Hören</h3><p>${esc(item.listen)}</p><h3>An der Form arbeiten</h3><p>${esc(item.form)}</p></details>${field('clip-'+item.id,'Deine Beobachtung mit Zeitstelle','Klang oder Form · Stelle im Video · Wirkung · fachliche Aussage')}<div class="feedback"><h3>Jetzt selbst schreiben</h3><p>${esc(item.writing)}</p><p class="small">Passende Grammatik: ${esc(listeningWorkshop(item.id).example.name)}</p><a class="button primary" href="#werkstatt?hoerbeispiel=${item.id}">Im Regel-Editor weiterschreiben</a></div></article>`).join('')}</div><aside class="panel exercise-notice"><h2>Und Mathematik, Physik, Schweizer Geschichte?</h2><p>Dazu gibt es hier eigene Schreibübungen und Beispielgrammatiken. Für diese Themen sind keine Wartke-Originaltracks hinterlegt. «Das Grundgesetz» behandelt Deutschland; die Übung zu den Schweizer Verfassungsdaten ist separat verfasst.</p><a href="#werkstatt">Zu den eigenen Fachübungen</a></aside><article class="panel"><h2>Wie arbeitet Wartke selbst?</h2><p>Im Gespräch mit der Kinderbuchpraxis spricht er ab etwa 32:10 über den Terra-X-Auftrag. Notiere den Unterschied zwischen einer künstlerischen Erfahrung und einem Beleg für eine Lernwirkung.</p>${sourceLink('podcast')}${field('poetology','Eine Beobachtung zu Wartkes Arbeitsweise','Quelle und Zeitstelle · seine Aussage in eigenen Worten · deine Anschlussfrage')}</article><p class="small section-gap">Beim Laden eines Players wird eine Verbindung zu YouTube oder Vimeo hergestellt. Es gibt kein automatisches Abspielen. Originaltexte und Aufnahmen werden nicht auf dieser Seite neu veröffentlicht.</p>`;}
function bindTrackFilters(){const query=new URLSearchParams(location.hash.split('?')[1]||''),wanted=query.get('thema')||'alle',buttons=[...document.querySelectorAll('[data-track-filter]')];const draw=id=>{const active=buttons.some(b=>b.dataset.trackFilter===id)?id:'alle';let count=0;document.querySelectorAll('[data-track-topic]').forEach(card=>{card.hidden=active!=='alle'&&card.dataset.trackTopic!==active;if(!card.hidden)count++;else if(card.querySelector('.original-cover iframe')){const item=MEDIA.find(m=>'track-'+m.id===card.id);card.querySelector('.original-cover').outerHTML=videoCover(item);}});bindMedia();buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.trackFilter===active)));$('#track-count').textContent=count+' Original'+(count===1?'':'e');};buttons.forEach(b=>b.onclick=()=>{const id=b.dataset.trackFilter;history.replaceState(null,'','#hoeren'+(id==='alle'?'':'?thema='+id));draw(id);if(parent!==window)parent.postMessage({type:'lyrik:route',unit:'wartke',hash:location.hash},location.origin);});draw(wanted);}
function bindMedia(){document.querySelectorAll('[data-media]').forEach(button=>button.onclick=()=>{const item=MEDIA.find(m=>m.id===button.dataset.media);const src=item.kind==='youtube'?`https://www.youtube-nocookie.com/embed/${item.video}`:`https://player.vimeo.com/video/${item.video}?dnt=1`;$('#player-'+item.id).innerHTML=`<iframe class="media-frame" title="${esc(item.title)}" src="${src}" allow="encrypted-media; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;});}
function formPage(){const pattern=Object.hasOwn(FORMS,note('form-pattern'))?note('form-pattern'):'paar';return head('Gedichtform','Was hält <em>die Zeilen zusammen?</em>','Untersuche einen eigens geschriebenen Übungstext. Du kannst die Endreime, den wiederholten Auftakt und die Sinneinheiten sichtbar machen.')+`<div class="grid"><section><div class="tabs" role="group" aria-label="Reimschema wählen">${Object.entries(FORMS).map(([key,form])=>`<button data-pattern="${key}" aria-pressed="${key===pattern}">${esc(form.name)} · ${form.scheme}</button>`).join('')}</div><div class="checks"><label><input id="show-rhyme" type="checkbox" checked> Endklänge</label><label><input id="show-anaphora" type="checkbox"> Wiederholter Auftakt</label><label><input id="show-chunks" type="checkbox"> Sinneinheiten</label></div><div id="form-text" class="form-stage"></div><p id="form-explanation" class="feedback"></p></section><aside class="panel"><h2>Vier Begriffe, vier Beobachtungen</h2><p><strong>Endreim:</strong> Klänge am Versende stimmen ab dem letzten betonten Vokal überein. Gleiche Schrift allein reicht nicht.</p><p><strong>Anapher:</strong> Mehrere aufeinanderfolgende Verse beginnen gleich – hier mit «Ich».</p><p><strong>Alliteration:</strong> Benachbarte betonte Wörter beginnen mit demselben Laut. Das ist etwas anderes als ein Endreim.</p><p><strong>Sprechgliederung:</strong> Pausen und Betonungen bilden Einheiten. Ein Zeilenbruch ist eine Möglichkeit, noch keine feste Sprechpause.</p><p class="small">Der Übungstext hat kein behauptetes durchgehendes Metrum. Prüfe am Vortrag, wo sich ein regelmässiger Puls tragen lässt.</p></aside></div><section class="panel"><h2>Den Takt als Versuch benutzen</h2><p>Lies langsam und lege versuchsweise vier Schläge unter einen Vers. Wo brauchst du mehr Zeit? Verändere dort den Vortrag oder den Wortlaut.</p><div class="metronome-controls"><button class="primary" id="beat-start">Viererschlag starten</button><div><label for="beat-tempo">Tempo: <output id="tempo-output">80</output> Schläge pro Minute</label><input id="beat-tempo" type="range" min="50" max="120" value="80"></div><label class="check-row"><input id="beat-sound" type="checkbox"> Leise Klicks einschalten</label></div><div class="beat-row" aria-hidden="true">${[1,2,3,4].map(n=>`<span class="beat">${n}</span>`).join('')}</div><p class="small">Der Puls unterstützt deinen Sprechversuch. Er bewertet weder Betonung noch Metrum automatisch.</p></section>${field('form-reflection','Was verändert die andere Zeilenfolge?','Nenne Reimschema, Wiederholung und eine Veränderung des Gedankengangs.')}<div class="actions"><a class="button primary" href="#werkstatt">Mit einer eigenen Form arbeiten</a></div>`;}
function bindForm(){
 const draw=()=>{const key=Object.hasOwn(FORMS,note('form-pattern'))?note('form-pattern'):'paar',form=FORMS[key];const rhyme=$('#show-rhyme').checked,anaphora=$('#show-anaphora').checked,chunks=$('#show-chunks').checked;$('#form-text').innerHTML='<p class="small">Übungstext dieser Einheit · kein Original von Bodo Wartke</p>'+form.order.map(index=>{const line=FORM_LINES[index];return `<p class="verse-line">${line.chunks.map((chunk,i)=>{let body=esc(chunk);if(i===0&&anaphora)body='<span class="anaphora">Ich</span>'+esc(chunk.slice(3));if(i===line.chunks.length-1&&rhyme)body=esc(chunk.slice(0,-line.end.length))+`<span class="rhyme-${line.group}">${esc(line.end)}</span>`;return chunks?`<span class="chunk">${body}</span>`:body;}).join(' ')}</p>`;}).join('')+`<p class="scheme">${rhymeScheme(form.order.map(i=>FORM_LINES[i].group))}</p>`;$('#form-explanation').textContent=form.hint+' Alle Ansichten verwenden dieselben vier Zeilen.';};
 document.querySelectorAll('[data-pattern]').forEach(button=>button.onclick=()=>{setNote('form-pattern',button.dataset.pattern);document.querySelectorAll('[data-pattern]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));draw();});
 for(const id of ['show-rhyme','show-anaphora','show-chunks'])$('#'+id).onchange=draw;
 const pulse=()=>{beatNumber=(beatNumber+1)%4;document.querySelectorAll('.beat').forEach((el,i)=>el.classList.toggle('active',i===beatNumber));if($('#beat-sound')?.checked&&audio){const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=beatNumber===0?760:520;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.06);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.07);}};
 const start=()=>{clearInterval(beatTimer);pulse();beatTimer=setInterval(pulse,60000/Number($('#beat-tempo').value));};
 $('#beat-start').onclick=async()=>{if(beatTimer){stopBeat();$('#beat-start').textContent='Viererschlag starten';return;}if($('#beat-sound').checked){try{audio??=new AudioContext();await audio.resume();}catch{toast('Der Browser unterstützt hier keinen Klang. Der sichtbare Puls funktioniert weiterhin.');}}start();$('#beat-start').textContent='Viererschlag stoppen';};
 $('#beat-sound').onchange=async()=>{if($('#beat-sound').checked){try{audio??=new AudioContext();await audio.resume();}catch{toast('Klang ist hier nicht verfügbar.');}}};
 $('#beat-tempo').oninput=()=>{$('#tempo-output').textContent=$('#beat-tempo').value;if(beatTimer)start();};draw();
}
function memoryPage(){return head('Mnemotechnik prüfen','Vorlage zu.<br><em>Was weisst du noch?</em>','Abrufen heisst: Wissen ohne sichtbare Vorlage wiedergeben. Teste es mit vier Aussagen. Entscheidend ist der fachliche Kern, nicht eine wortgetreue Wiederholung.')+`<div class="grid"><section class="panel"><h2>Einen Abrufversuch beginnen</h2><label class="field" for="memory-topic">Thema</label><select id="memory-topic">${TOPICS.map(topic=>`<option value="${topic.id}" ${topic.id===note('memory-topic','deutsch')?'selected':''}>${topic.subject} · ${topic.title}</option>`).join('')}</select><label class="field" for="memory-mode">Vorlage</label><select id="memory-mode"><option value="facts">Sachliche Aussagen</option><option value="verse" ${note('memory-mode')==='verse'?'selected':''}>Versfassung</option></select><button class="primary" id="memory-start" style="margin-top:20px">Versuch beginnen</button><p class="small" style="margin-top:16px">Beide Fassungen enthalten dieselben vier Lernziele. Versfassungen sind eigens geschrieben und unterschiedlich stark gereimt. Wähle selbst eine angemessene Lernzeit.</p></section><aside class="panel blue"><h2>Woran du die Hilfe erkennst</h2><p>Ein wiederkehrender Klang kann eine nächste Zeile nahelegen. Ein Rhythmus kann Stoff gliedern. Ob der Inhalt verfügbar ist, zeigt erst dein Abruf.</p><p>Ein einzelner Selbstversuch beweist keine Lernwirkung. Vorwissen, Textschwierigkeit, Übungszeit und die Reihenfolge beeinflussen dein Ergebnis.</p><p>Prüfe denselben Zusammenhang in der nächsten Stunde noch einmal – und wende ihn an einer neuen Aufgabe an.</p>${sourceLink('retrieval')}</aside></div><section id="recall-area"></section><section class="section-gap"><h2>Drei Gedächtnishilfen ausprobieren</h2><div class="grid three"><article class="panel"><h3>Ein Klang als Hinweis</h3><p>Wähle ein Schlüsselwort als Versende. Suche einen passenden Reim und formuliere dann die fachliche Aussage. Prüfe, ob der Reim beim Abrufen die nächste Aussage nahelegt.</p></article><article class="panel"><h3>Sinnvolle Gruppen</h3><p>Ordne vier Fakten zu zwei Sinnpaaren. Gib jedem Paar einen wiederholten Auftakt oder einen gemeinsamen Takt. Erkläre danach, warum die Aussagen zusammengehören.</p></article><article class="panel"><h3>Eine Folge von Bildern</h3><p>Verbinde jeden der vier Fakten mit einem konkreten Bild an einem vertrauten Ort. Gehe die Orte gedanklich ab. Übersetze jedes Bild zurück in eine fachlich genaue Aussage.</p></article></div><p class="small">Das sind Schreib- und Lernversuche, keine Erfolgsgarantie. Ein Bild darf den Zusammenhang vereinfachen, aber nicht verfälschen. Prüfe auch später ohne Vorlage, was die Hilfe trägt.</p>${field('mnemonic-plan','Meine Merkhilfe und ihre Grenzen','Fakt · Klang, Sinnpaar oder Bild · Was könnte ich dabei verwechseln?')}</section><section class="panel section-gap"><h2>Deine gespeicherten Versuche</h2><div id="attempt-history"></div>${field('memory-reflection','Welche Hilfe hat getragen – und wo gab es eine Lücke?','Habe ich einen Klang erinnert, eine Zahl verwechselt oder einen Zusammenhang erklärt? Was prüfe ich beim nächsten Mal?')}</section>`;}
function bindMemory(){
 const drawHistory=()=>{$('#attempt-history').innerHTML=state.attempts.length?state.attempts.slice().reverse().map(attempt=>`<p><strong>${esc(TOPICS.find(t=>t.id===attempt.topic).subject)}</strong> · ${attempt.mode==='facts'?'Aussagen':'Versfassung'} · ${scoreRecall(attempt.checks)}/4 Kerne nach eigener Prüfung · ${esc(new Date(attempt.date).toLocaleDateString('de-CH',{timeZone:'Europe/Zurich'}))}</p>`).join(''):'<p class="small">Noch kein Versuch gespeichert.</p>';};
 const draw=()=>{const area=$('#recall-area');if(!recall){area.innerHTML='';return;}const topic=TOPICS.find(t=>t.id===recall.topic);if(recall.stage==='study'){area.innerHTML=`<article class="panel ink"><p class="eyebrow" style="color:#f7bd52">Deine Vorlage · ${esc(topic.subject)}</p><h2>${esc(topic.title)}</h2><div class="study-text">${esc((recall.mode==='facts'?topic.facts:topic.verse).join('\n\n'))}</div><p class="small" style="margin-top:20px">${esc(topic.note)}</p><button class="button" id="memory-hide" style="background:#f7bd52;color:#152137">Vorlage verdecken und abrufen</button></article>`;$('#memory-hide').onclick=()=>{recall=hideRecall(recall);draw();$('#recall-answer-0').focus();};}else if(recall.stage==='recall'){area.innerHTML=`<article class="panel"><p class="eyebrow">Ohne Vorlage · ${esc(topic.subject)}</p><h2>Antworte aus dem Gedächtnis.</h2><p>Auch eine Lücke ist ein Ergebnis. Du kannst sie beim Vergleichen festhalten.</p>${topic.questions.map((q,i)=>`<label class="field" for="recall-answer-${i}">${i+1}. ${esc(q)}</label><textarea id="recall-answer-${i}" maxlength="5000" rows="2" style="min-height:80px"></textarea>`).join('')}<button id="memory-compare" class="primary" style="margin-top:20px">Mit den Antwortkernen vergleichen</button></article>`;$('#memory-compare').onclick=()=>{recall=compareRecall(recall,topic.questions.map((_,i)=>$('#recall-answer-'+i).value));draw();};}else{area.innerHTML=`<article class="panel"><p class="eyebrow">Eigene Prüfung · ${esc(topic.subject)}</p><h2>Was steckt in deiner Antwort?</h2>${topic.questions.map((q,i)=>`<div class="recall-question"><h3>${esc(q)}</h3><p><strong>Deine Antwort:</strong> ${esc(recall.answers[i]||'Keine Antwort notiert.')}</p><p class="answer-key"><strong>Antwortkern:</strong> ${esc(topic.answers[i])}</p><label class="check-row"><input type="checkbox" data-recall-check="${i}" ${recallSaved?'disabled':''} ${recall.checks[i]?'checked':''}> Meine Antwort enthält diesen Kern inhaltlich richtig.</label></div>`).join('')}<p class="result-count" id="recall-score">${scoreRecall(recall.checks)}/4</p><p class="small">Selbsteinschätzung, keine automatische Benotung. Vergleiche eine unsichere Stelle mit der Fachquelle.</p>${sourceLink(topic.source)}<div class="actions"><button id="memory-save" class="primary" ${recallSaved?'disabled':''}>${recallSaved?'Versuch gespeichert':'Versuch im Journal speichern'}</button><button id="memory-repeat">Noch einmal ohne Vorlage</button></div></article>`;document.querySelectorAll('[data-recall-check]').forEach(check=>check.onchange=()=>{recall.checks[Number(check.dataset.recallCheck)]=check.checked;$('#recall-score').textContent=scoreRecall(recall.checks)+'/4';$('#memory-save').disabled=false;recallSaved=false;});$('#memory-save').onclick=()=>{if(recallSaved)return;try{state=saveAttempt(state,recall);save();recallSaved=true;$('#memory-save').disabled=true;$('#memory-save').textContent='Versuch gespeichert';document.querySelectorAll('[data-recall-check]').forEach(check=>check.disabled=true);drawHistory();}catch(error){toast(error.message);}};$('#memory-repeat').onclick=()=>{recall=hideRecall(startRecall(recall.topic,recall.mode));recallSaved=false;draw();};}};
 $('#memory-start').onclick=()=>{const topic=$('#memory-topic').value,mode=$('#memory-mode').value;setNote('memory-topic',topic);setNote('memory-mode',mode);recall=startRecall(topic,mode);recallSaved=false;draw();};draw();drawHistory();
}
function workshop(){const from=workshopRoute(location.hash).media;const chosen=from?.transfer||(TOPICS.some(t=>t.id===note('workshop-topic'))||note('workshop-topic')==='eigen'?note('workshop-topic'):'math');return head('Bodo Wartke · Deine Schreibwerkstatt','Ein Wort.<br><em>Was machst du daraus?</em>','Fang klein an: ein Klang, eine Figur, eine überraschende Zeile. Für Lernverse nimmst du danach einen Zusammenhang dazu, den du dir merken möchtest.')+spark()+`${note('studio-impuls')?`<aside class="feedback"><h2>Dein Gedanke aus dem gemeinsamen Einstieg</h2><p>${esc(note('studio-impuls'))}</p><p class="small">Nimm diese Zeile als Anfang. Im Regel-Editor kannst du eigene Wörter und mögliche Fortsetzungen ausprobieren.</p></aside>`:''}<p class="workshop-bridge"><a href="../#werkstatt">Zu Lösels Schreibwerkstatt: Bilder, Gefühle und Wendungen</a></p><details class="learning-workbench"><summary>Aus der Zeile werden Lernverse · Fach, Inhalt und vier Verse</summary><label class="field" for="workshop-topic">Fach und Ausgangspunkt</label><select id="workshop-topic">${TOPICS.map(topic=>`<option value="${topic.id}" ${topic.id===chosen?'selected':''}>${esc(topic.id===from?.transfer?listeningWorkshop(from.id).topic.title:topic.subject+' · '+topic.title)}</option>`).join('')}<option value="eigen" ${chosen==='eigen'?'selected':''}>Ein eigenes Thema</option></select><div class="actions"><button id="open-dgram">Zum D-Gram-Regel-Editor</button></div><div id="workshop-area"></div></details><section id="grammar-stage"></section><section class="section-gap"><h2>Klingt richtig. Ist es das auch?</h2><p>Prüfe die Aussage unabhängig von ihrer sprachlichen Form.</p>${FACT_CHECKS.map(check=>`<article class="panel question-card"><p class="study-text">${esc(check.verse)}</p><div class="actions"><button data-fact="${check.id}" data-answer="true">Der Kern stimmt</button><button data-fact="${check.id}" data-answer="false">Der Kern ist falsch</button></div><div id="fact-result-${check.id}" role="status"></div></article>`).join('')}</section>`;}
function bindWorkshop(){
 $('#grammar-stage').innerHTML=grammarEditorHTML();
 const draw=()=>{const id=$('#workshop-topic').value,from=workshopRoute(location.hash).media,handoff=from?.transfer===id?listeningWorkshop(from.id):null,topic=handoff?.topic||TOPICS.find(t=>t.id===id),context=handoff?.context||id,prefix='ws-'+context;setNote('workshop-topic',id);const facts=topic?.facts||['','','',''],terms=topic?.terms||[];$('#workshop-area').innerHTML=`<div class="grid"><section class="panel"><p class="eyebrow">Zuerst der Inhalt</p><h2>Vier Aussagen, die stimmen sollen</h2><p class="small">Prüfe Fachwörter, Bedingungen, Zahlen und Reihenfolge. Bei einem Themenwechsel bleibt dein bisheriger Entwurf unter seinem Thema gespeichert.</p>${facts.map((fact,i)=>`<label class="field" for="${prefix}-fact-${i}">Aussage ${i+1}</label><textarea id="${prefix}-fact-${i}" data-work-note="${prefix}-fact-${i}" maxlength="5000" rows="2" style="min-height:80px">${esc(note(prefix+'-fact-'+i,fact))}</textarea>`).join('')}${topic?`<p class="small" style="margin-top:16px">${esc(topic.note)}</p>${sourceLink(topic.source)}`:''}<label class="field" for="${prefix}-source">Deine fachliche Quelle · Titel, Seite oder URL</label><input type="text" id="${prefix}-source" data-work-note="${prefix}-source" maxlength="1000" value="${esc(note(prefix+'-source',topic?source(topic.source).title:''))}" placeholder="Zum Beispiel dein Lehrbuch mit Seitenzahl"><label class="field" for="${prefix}-terms">Fachwörter, die erhalten bleiben sollen · mit Komma trennen</label><input type="text" id="${prefix}-terms" data-work-note="${prefix}-terms" maxlength="1000" value="${esc(note(prefix+'-terms',terms.join(', ')))}"></section><section class="panel blue"><p class="eyebrow">Dann die Form</p><h2>Vier Verse ausprobieren</h2><label class="field" for="${prefix}-shape">Formvorschlag</label><select id="${prefix}-shape" data-work-note="${prefix}-shape">${[['paar','Paarreim · aabb'],['kreuz','Kreuzreim · abab'],['frei','Freie Sprechverse']].map(([key,title])=>`<option value="${key}" ${key===note(prefix+'-shape',handoff?'frei':'paar')?'selected':''}>${title}</option>`).join('')}</select><p class="small" id="workshop-shape-hint" style="margin-top:14px"></p><div class="draft-grid">${[0,1,2,3].map(i=>`<div><label class="field" for="${prefix}-line-${i}">Vers ${i+1}</label><textarea id="${prefix}-line-${i}" data-work-note="${prefix}-line-${i}" maxlength="5000" rows="3" placeholder="Eine fachlich richtige Aussage bekommt eine Form …">${esc(note(prefix+'-line-'+i))}</textarea></div>`).join('')}</div><div class="actions"><button id="load-workshop-example">Übungsverse als Ausgangspunkt laden</button></div><p class="small">Eigens verfasste Übungstexte zu den ursprünglichen Fachangaben. Wenn du die Fakten geändert hast, passe auch die Verse an. Das Laden ersetzt die vier aktuellen Versfelder erst nach deiner Bestätigung.</p><div id="term-check" class="feedback"></div>${[0,1,2,3].map(i=>`<label class="check-row" style="margin:12px 0"><input type="checkbox" data-work-check="${prefix}-check-${i}" ${note(prefix+'-check-'+i)==='ja'?'checked':''}> Aussage ${i+1} ist im Entwurf fachlich erhalten.</label>`).join('')}<label class="field" for="${prefix}-revision">Eine bewusste Überarbeitung</label><textarea id="${prefix}-revision" data-work-note="${prefix}-revision" maxlength="10000" placeholder="Vorher · nachher · Wirkung auf Sinn, Klang oder Abruf">${esc(note(prefix+'-revision'))}</textarea></section></div><section class="panel ink section-gap"><p class="eyebrow" style="color:#f7bd52">Deine Sprechfassung</p><div id="workshop-preview" class="poem-preview"></div><p id="workshop-endwords" class="small endwords"></p><div class="actions"><button id="workshop-export" style="background:#f7bd52;color:#152137">Text als Datei sichern</button><button id="workshop-print" style="color:#f6f2e9;border-color:#a8b8cf">Druckansicht</button></div><p class="small">Trage vor, lass die Vorlage verschwinden und bitte jemand anderen, den fachlichen Kern zu erklären. Eine schwierige Lautfolge muss nicht schnell gesprochen werden.</p></section>`;
  const lines=()=>[0,1,2,3].map(i=>$('#'+prefix+'-line-'+i).value);
  const update=()=>{const values=lines(),text=values.join('\n'),terms=$('#'+prefix+'-terms').value.split(',').map(t=>t.trim()).filter(Boolean).slice(0,40),coverage=termCoverage(text,terms);$('#workshop-preview').textContent=text.trim()||'Hier erscheinen deine vier Verse.';$('#workshop-endwords').textContent='Aktuelle Versenden: '+endWords(values).join(' · ');$('#term-check').textContent=terms.length?`Fachwörter wörtlich gefunden: ${coverage.filter(t=>t.found).length}/${terms.length}. ${coverage.some(t=>!t.found)?'Noch nicht gefunden: '+coverage.filter(t=>!t.found).map(t=>t.term).join(', ')+'. ':''}Das Vorkommen eines Wortes prüft seine Bedeutung und die fachliche Richtigkeit nicht automatisch.`:'Trage Fachwörter ein, die du im Entwurf wiederfinden möchtest.';const shape=$('#'+prefix+'-shape').value;$('#workshop-shape-hint').textContent=shape==='paar'?'Endklänge: A · A · B · B. Beginne mit einem Sinnpaar, nicht mit einem beliebigen Reim.':shape==='kreuz'?'Endklänge: A · B · A · B. Verbinde inhaltlich passende Aussagen über die Distanz.':'Arbeite mit klaren Sinneinheiten, Wiederholungen und Atempausen. Ein Endreim ist hier keine Vorgabe.';};
  document.querySelectorAll('[data-work-note]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.workNote]=el.value;if(/-(fact|line)-/.test(el.dataset.workNote))document.querySelectorAll('[data-work-check]').forEach(check=>{check.checked=false;state.notes[check.dataset.workCheck]='nein';});save();update();}));document.querySelectorAll('[data-work-check]').forEach(el=>el.onchange=()=>setNote(el.dataset.workCheck,el.checked?'ja':'nein'));
  $('#load-workshop-example').onclick=()=>{if(!topic)return toast('Sammle für das eigene Thema zuerst Fakten und formuliere eigene Verse.');modal('<h2>Übungsverse laden?</h2><p>Die vier aktuellen Versfelder dieses Themas werden ersetzt. Deine Fakten und die Entwürfe der anderen Themen bleiben erhalten.</p><div class="actions"><button id="example-cancel">Abbrechen</button><button class="primary" id="example-confirm">Übungsverse laden</button></div>');$('#example-cancel').onclick=()=>$('#dialog').close();$('#example-confirm').onclick=()=>{topic.verse.forEach((line,i)=>{setNote(prefix+'-line-'+i,line);$('#'+prefix+'-line-'+i).value=line;});document.querySelectorAll('[data-work-check]').forEach(check=>{check.checked=false;state.notes[check.dataset.workCheck]='nein';});save();$('#dialog').close();update();};};
  $('#workshop-export').onclick=()=>download('meine-lernverse.txt',`${topic?.subject||'Eigenes Thema'} · Lernverse\n\n${lines().join('\n')}\n\nFachliche Ausgangsaussagen:\n${[0,1,2,3].map(i=>$('#'+prefix+'-fact-'+i).value).join('\n')}\n\nQuelle: ${$('#'+prefix+'-source').value}\n\nÜberarbeitung: ${$('#'+prefix+'-revision').value}\n`);
  $('#workshop-print').onclick=()=>{modal(`<h2>Meine Lernverse</h2><div class="poem-preview">${esc(lines().join('\n'))}</div><p class="small" style="margin-top:20px">Quelle: ${esc($('#'+prefix+'-source').value)}</p><button id="print-confirm">Jetzt drucken</button>`);$('#print-confirm').onclick=()=>window.print();};update();
  mountGrammarEditor($('#dgram-editor'),{topic:id,context,initialExample:handoff?.example,hearing:handoff?.media,note,setNotes:values=>{Object.assign(state.notes,values);save();},getLibrary:()=>state.grammars||[],setLibrary:entries=>{state.grammars=entries;save();},modal,closeModal:()=>$('#dialog').close(),download,onTransfer:(target,verses)=>{const targetPrefix=target===id?prefix:'ws-'+target;verses.forEach((line,i)=>{state.notes[targetPrefix+'-line-'+i]=line;state.notes[targetPrefix+'-check-'+i]='nein';});state.notes['workshop-topic']=target;save();$('#workshop-topic').value=target;if(target!==id&&handoff){location.hash='werkstatt';return;}draw();$('.learning-workbench').open=true;$('#'+targetPrefix+'-line-0').focus();$('#'+targetPrefix+'-line-0').scrollIntoView({block:'center'});toast('Vier Verse übernommen. Prüfe sie an deinen Ausgangsaussagen und an der Fachquelle.');}});
 };
 $('#open-dgram').onclick=()=>{$('#dgram-editor').scrollIntoView({block:'start',behavior:'instant'});($('#dg-hearing-note')||$('#dg-example')).focus({preventScroll:true});};
 $('#workshop-topic').onchange=draw;draw();document.querySelectorAll('[data-fact]').forEach(button=>button.onclick=()=>{const check=FACT_CHECKS.find(item=>item.id===button.dataset.fact),right=check.correct===(button.dataset.answer==='true');$('#fact-result-'+check.id).innerHTML=`<p class="feedback">${right?'Deine Prüfung passt.':'Prüfe den Inhalt noch einmal.'} ${esc(check.explanation)}</p>${sourceLink(check.source)}`;});
}
function sourcesPage(){return head('Quellen & Unterricht','Form bewusst einsetzen.<br><em>Inhalt überprüfen.</em>','Die Einheit verbindet die Untersuchung von Originalen mit eigenen Übungstexten und einer kritischen Prüfung von Gedächtnishilfen.')+`<section class="grid"><article class="panel"><h2>Für zwei Lektionen</h2><table class="plan"><thead><tr><th>Phase</th><th>Auftrag</th><th>Zeit</th></tr></thead><tbody>${[['Hören','Einen biologischen und einen sprachlichen Originalbeitrag vergleichen.','15 Min.'],['Form','Endreime, Auftakt und Sinneinheiten untersuchen; Anordnung wechseln.','20 Min.'],['Abrufen','Eine Vorlage verdecken, vier Antwortkerne prüfen.','15 Min.'],['Schreiben','Vier Fakten in Lernverse überführen und fachlich gegenlesen lassen.','30 Min.'],['Vortragen','Sprechfassung prüfen; später erneut ohne Vorlage erklären.','10 Min.']].map(row=>`<tr>${row.map(value=>`<td>${value}</td>`).join('')}</tr>`).join('')}</tbody></table></article><article class="panel blue"><h2>Rückmeldung ohne Tempodruck</h2><ul class="fact-list"><li>Die vier fachlichen Kerne stimmen und ihre Bedingungen bleiben erhalten.</li><li>Die gewählte Gedichtform ist hör- oder sichtbar und lässt sich begründen.</li><li>Der Vortrag gliedert den Text verständlich. Schnelligkeit ist kein Qualitätsmass.</li><li>Ein Abrufversuch zeigt eine Stärke und eine konkrete Lücke.</li><li>Eine Überarbeitung verbessert die Form, ohne Wissen zu verfälschen.</li></ul><p class="small">Basis: zwei Fakten und freie Sprechverse. Erweiterung: mehrsilbige Reime, zusätzliche Quellenprüfung oder Vergleich verschiedener Lernhilfen in der nächsten Stunde.</p></article></section><section class="panel"><h2>Was die Forschung hier leistet</h2><p>Aktives Abrufen ist in der Lernforschung gut untersucht. Daraus folgt kein Versprechen, dass jeder Rap besser lehrt als ein Sachtext. Rhythmus, Reim und Geschichten sind mögliche Abrufhilfen; fachliche Erklärung und spätere Anwendung bleiben eigene Aufgaben.</p><p>Eine weitere Studie zeigt, dass ästhetische Form bei der Beurteilung von Sprüchen mit wahrgenommener Wahrheit zusammenhängen kann. Die Rechen- und Datumsaufgaben dieser Einheit lassen deshalb den Inhalt gegen den Klang prüfen.</p><p class="small">Unser Abrufversuch hat keine zufällige Gruppenzuweisung und kontrolliert Vorwissen oder Textschwierigkeit nicht. Er dient der eigenen Beobachtung und Rückmeldung.</p></section><section class="section-gap"><h2>Originalbeiträge und fachliche Grundlagen</h2><ol class="source-list">${SOURCES.map(item=>`<li><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a><p class="small">${esc(item.note)}</p></li>`).join('')}${MEDIA.map(item=>`<li><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a><p class="small">${esc(item.provider)} · Originalquelle für die Höraufgabe.</p></li>`).join('')}</ol><p class="small">Links und Quellen geprüft am 28.11.2026. Einbettungen, Verfügbarkeit und etwaige Anmeldungen liegen beim Anbieter. Die Website selbst setzt keine Analyse- oder Trackingdienste ein.</p></section><section class="panel section-gap"><h2>Eigene Texte, eigene Daten</h2><p>Alle Übungsverse, Fachübertragungen und Arbeitsaufträge sind für diese Ressource geschrieben. Es werden keine vollständigen Wartke-Liedtexte kopiert und keine Originalaufnahmen neu gehostet. Die eingebundenen Originale sind von den bearbeitbaren Übungen getrennt.</p><p>Notizen und Entwürfe bleiben lokal in diesem Browser. Du kannst sie sichern und auf einem anderen Gerät wieder laden. Bei gemeinsam benutzten Geräten können andere Personen die lokalen Einträge sehen.</p><p><a href="../">Zur ersten Ressource über Clara Lösel</a></p></section>`;}
$('#journal-export').onclick=()=>download('wartke-lernjournal.json',JSON.stringify(state,null,2),'application/json');
$('#journal-import').onchange=async event=>{const input=event.target;try{const file=input.files[0];if(!file)return;if(file.size>1000000)throw Error('Die Sicherung ist zu gross (maximal 1 MB).');const next=decodeJournal(await file.text());modal('<h2>Sicherung laden?</h2><p>Die ausgewählte Wartke-Sicherung ersetzt das aktuelle Journal dieser Ressource. Die Clara-Lösel-Einträge sind davon unabhängig.</p><div class="actions"><button id="import-backup">Aktuelles Journal zuerst sichern</button><button id="import-cancel">Abbrechen</button><button class="primary" id="import-confirm">Sicherung übernehmen</button></div>');$('#import-backup').onclick=$('#journal-export').onclick;$('#import-cancel').onclick=()=>$('#dialog').close();$('#import-confirm').onclick=()=>{state=next;save();recall=null;recallSaved=false;$('#dialog').close();render();toast('Wartke-Sicherung geladen.');};}catch(error){toast(error.message);}finally{input.value='';}};
function focusWorkshopEntry(){if(location.hash.startsWith('#werkstatt?')&&new URLSearchParams(location.hash.split('?')[1]).get('editor')==='regeln'){$('#exchange-fold').open=true;$('#workshop-exchange').scrollIntoView({block:'start',behavior:'instant'});$('#workshop-exchange').focus({preventScroll:true});}else if(workshopRoute(location.hash).media){$('#dgram-editor').scrollIntoView({block:'start',behavior:'instant'});($('#dg-hearing-note')||$('#dg-example')).focus({preventScroll:true});}else{$('#main').focus();window.scrollTo(0,0);}}
window.addEventListener('hashchange',()=>{render();focusWorkshopEntry();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&beatTimer){stopBeat();if($('#beat-start'))$('#beat-start').textContent='Viererschlag starten';}});
render();if(workshopRoute(location.hash).media||location.hash.includes('editor=regeln'))focusWorkshopEntry();if(!storage)toast('Bitte sichere dein Journal regelmässig als Datei. Der lokale Speicher konnte nicht gelesen werden.');

window.addEventListener('studio:prompt',event=>{setNote('studio-impuls',event.detail);setNote('workshop-topic','eigen');render();});
